        return list(batches)
    if sum(batches) < order_qty:
        return list(batches)
    remaining_order = order_qty
    updated: list[int] = []
    for qty in batches:
        if remaining_order <= 0:
            updated.append(qty)
        elif qty >= remaining_order:
            updated.append(qty - remaining_order)
            remaining_order = 0
        else:
            updated.append(0)
            remaining_order -= qty
    return updated

